65: function startAudio() {
66:   const AudioContext = window.AudioContext || window.webkitAudioContext;
67:   if (!AudioContext) return;
68:   if (!audio.context) {
69:     audio.context = new AudioContext();
70:     audio.master = audio.context.createGain();
71:     audio.master.gain.value = 0.13;
72:     audio.master.connect(audio.context.destination);
73:     audio.drive = audio.context.createWaveShaper();
74:     const curve = new Float32Array(4096);
75:     for (let i = 0; i < curve.length; i += 1) {
76:       const x = (i * 2) / curve.length - 1;
77:       curve[i] = Math.tanh(x * 5);
78:     }
79:     audio.drive.curve = curve; audio.drive.oversample = '4x'; audio.drive.connect(audio.master);
80:   }
81:   audio.context.resume();
82:   if (audio.musicTimer) return;
83:   const riff = [41.2, 41.2, 49, 41.2, 55, 49, 41.2, 61.7, 41.2, 41.2, 49, 55, 41.2, 49, 36.7, 41.2];
84:   audio.musicTimer = window.setInterval(() => {
85:     if (!world.running || !audio.context) return;
86:     const ctx = audio.context;
87:     const now = ctx.currentTime;
88:     const step = audio.musicStep++ % riff.length;
89:     if ([0, 4, 8, 12].includes(step)) {
90:       const kick = ctx.createOscillator(); const volume = ctx.createGain();
91:       kick.type = 'sine'; kick.frequency.setValueAtTime(115, now); kick.frequency.exponentialRampToValueAtTime(38, now + 0.12);
92:       volume.gain.setValueAtTime(0.28, now); volume.gain.exponentialRampToValueAtTime(0.001, now + 0.14);
93:       kick.connect(volume); volume.connect(audio.master); kick.start(now); kick.stop(now + 0.15);
94:     } else if ([2, 6, 10, 14].includes(step)) {
95:       const snare = ctx.createOscillator(); const volume = ctx.createGain();
96:       snare.type = 'triangle'; snare.frequency.value = 175;
97:       volume.gain.setValueAtTime(0.12, now); volume.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
98:       snare.connect(volume); volume.connect(audio.master); snare.start(now); snare.stop(now + 0.09);
99:     }
100:     if (step % 2 === 0) {
101:       const root = riff[step];
102:       [root, root * 1.5].forEach((frequency) => {
103:         const osc = ctx.createOscillator(); const gain = ctx.createGain(); const filter = ctx.createBiquadFilter();
104:         osc.type = 'sawtooth'; osc.frequency.value = frequency;
105:         filter.type = 'lowpass'; filter.frequency.value = 420;
106:         gain.gain.setValueAtTime(0.095, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
107:         osc.connect(filter); filter.connect(gain); gain.connect(audio.drive); osc.start(now); osc.stop(now + 0.21);
108:       });
109:     }
110:   }, 220);
111: }
112: function playZombieMoan() {
