function updatePickups(dt) {
  for (let i = world.pickups.length - 1; i >= 0; i -= 1) {
    const item = world.pickups[i]; item.bob += dt * 4;
    item.model.position.copy(toScene(item.x, item.y, 0.42 + Math.sin(item.bob) * 0.07));
