200: function applyZombieAsset(zombie) {
201:   if (!zombieAsset.root || !window.THREE.SkeletonUtils) return false;
202:   const replacement = THREE.SkeletonUtils.clone(zombieAsset.root);
203:   replacement.traverse((part) => {
204:     if (!part.isMesh) return;
205:     part.castShadow = true;
206:     part.receiveShadow = true;
207:     const cloneMaterial = (material) => {
208:       const instance = material.clone();
209:       if (instance.emissive) instance.userData.baseEmissive = instance.emissive.clone();
210:       return instance;
211:     };
212:     part.material = Array.isArray(part.material) ? part.material.map(cloneMaterial) : cloneMaterial(part.material);
213:   });
214:   replacement.updateWorldMatrix(true, true);
215:   const bounds = new THREE.Box3().setFromObject(replacement);
216:   const size = bounds.getSize(new THREE.Vector3());
217:   if (!Number.isFinite(size.y) || size.y < 0.1) return false;
218:   const center = bounds.getCenter(new THREE.Vector3());
219:   const scale = 1.65 / size.y;
220:   replacement.scale.setScalar(scale);
221:   replacement.position.set(-center.x * scale, -bounds.min.y * scale, -center.z * scale);
222:   const root = new THREE.Group();
223:   root.add(replacement);
224:   if (zombie.model) {
225:     scene.remove(zombie.model);
226:     zombie.model.traverse((part) => { if (part.geometry) part.geometry.dispose(); });
227:   }
228:   scene.add(root);
229:   zombie.model = root;
230:   zombie.limbs = [];
231:   zombie.mixer = new THREE.AnimationMixer(replacement);
232:   if (zombieAsset.clips.length) {
233:     zombie.action = zombie.mixer.clipAction(zombieAsset.clips[0]);
234:     zombie.action.setLoop(THREE.LoopRepeat, Infinity);
235:     zombie.action.play();
236:   }
237:   syncEntity(zombie);
238:   return true;
239: }
